static int gve_tx_fifo_init ( struct gve_priv * priv , struct gve_tx_fifo * fifo ) { fifo -> base = vmap ( fifo -> qpl -> pages , fifo -> qpl -> num_entries , VM_MAP , PAGE_KERNEL ) ; if ( unlikely ( ! fifo -> base ) ) { netif_err ( priv , drv , priv -> dev , "Failed to vmap fifo, qpl_id = %d\n" , fifo -> qpl -> id ) ; return - ENOMEM ; } fifo -> size = fifo -> qpl -> num_entries * PAGE_SIZE ; atomic_set ( & fifo -> available , fifo -> size ) ; return 0 ; } 